/**
 * Runtime secrets for the API Worker on a self-hosted celld box.
 *
 * celld has no secret mechanism, and whatever is in a deployment's `vars` is stored in plaintext
 * in the fleet bucket for every version. So on a box the deploy passes no secret at all: the
 * Worker gets them at runtime from the box-local key agent (deploy/selfhost/key-agent), which
 * opens the sealed bundle with the operator's key service. They live only in this isolate's
 * memory.
 *
 * Only the celld entry module (generated by scripts/selfhost/celld-project.ts) imports this file.
 * The Cloudflare build's entry is `src/index.ts`, which does not, so Cloudflare installs keep
 * their Worker secret bindings and never run this code.
 *
 * Cost: one loopback request per isolate (celld retires idle stateless isolates every 30 s pool
 * tick), shared by every request that arrives while it is in flight. If the agent is down the
 * Worker fails closed: HTTP 503 `SECRETS_UNAVAILABLE`, a failed cron run, a Durable Object that
 * refuses its events. Nothing runs without its secrets.
 */

import { log } from '../lib/logger';
import { type JsonRecord, maybeJsonRecord } from '../lib/runtime-validation';
import { setPreviousEncryptionKeys } from '../services/encryption-key-fallback';
import { KEY_ROTATION_PATH } from './key-rotation/control-auth';
import { type AesKeyEnv, previousKeyPairs } from './key-rotation/keys';

export const DEFAULT_KEY_AGENT_TIMEOUT_MS = 3000;
const AGENT_URL = /^http:\/\/127\.0\.0\.1:\d{1,5}\/v1\/secrets$/;
const BUNDLE_ID = /^[0-9a-f]{32}$/;
const SECRET_NAME = /^[A-Z_][A-Z0-9_]*$/;

export interface KeyAgentEnv {
  /** `http://127.0.0.1:<port>/v1/secrets`; written by the self-host deploy. */
  SAM_KEY_AGENT_URL?: string;
  /** The sealed bundle this deployment was built with; a content-free random id. */
  SAM_SECRET_BUNDLE_ID?: string;
  /** Raw Ed25519 public key (base64) the agent's answers must verify under. Not a secret. */
  SAM_KEY_AGENT_VERIFY_KEY?: string;
  /** Bound into the request: the agent refuses a bundle sealed for another install. */
  SAM_INSTALLATION_ID?: string;
  SAM_KEY_AGENT_TIMEOUT_MS?: string;
}

export const SIGNATURE_HEADER = 'x-sam-key-agent-signature';
/** Names the agent's answer may never set: the channel's own settings. */
const PROTECTED_NAMES = new Set([
  'SAM_KEY_AGENT_URL',
  'SAM_SECRET_BUNDLE_ID',
  'SAM_KEY_AGENT_VERIFY_KEY',
  'SAM_KEY_AGENT_TIMEOUT_MS',
  'SAM_INSTALLATION_ID',
]);

export type RuntimeSecrets = Readonly<Record<string, string>>;

export class RuntimeSecretsUnavailableError extends Error {
  readonly code: string;
  constructor(code: string, message: string) {
    super(message);
    this.name = 'RuntimeSecretsUnavailableError';
    this.code = code;
  }
}

let cached: { bundleId: string; secrets: RuntimeSecrets } | null = null;
let inflight: { bundleId: string; promise: Promise<RuntimeSecrets> } | null = null;

/** For tests: forget this isolate's copy, as a fresh isolate would. */
export function resetRuntimeSecretsForTests(): void {
  cached = null;
  inflight = null;
}

interface AgentSettings {
  url: string;
  bundleId: string;
  verifyKey: Uint8Array;
  installationId: string;
  timeoutMs: number;
}

function settings(env: KeyAgentEnv): AgentSettings {
  const url = env.SAM_KEY_AGENT_URL ?? '';
  const bundleId = env.SAM_SECRET_BUNDLE_ID ?? '';
  let verifyKey = new Uint8Array();
  try {
    verifyKey = Uint8Array.from(atob(env.SAM_KEY_AGENT_VERIFY_KEY ?? ''), (c) => c.charCodeAt(0));
  } catch {
    // reported below
  }
  if (!AGENT_URL.test(url) || !BUNDLE_ID.test(bundleId) || verifyKey.length !== 32) {
    throw new RuntimeSecretsUnavailableError(
      'SECRETS_MISCONFIGURED',
      'SAM_KEY_AGENT_URL must be http://127.0.0.1:<port>/v1/secrets, SAM_SECRET_BUNDLE_ID a bundle id ' +
        'and SAM_KEY_AGENT_VERIFY_KEY an Ed25519 public key'
    );
  }
  const timeout = Number.parseInt(env.SAM_KEY_AGENT_TIMEOUT_MS ?? '', 10);
  return {
    url,
    bundleId,
    verifyKey,
    installationId: env.SAM_INSTALLATION_ID ?? '',
    timeoutMs:
      Number.isSafeInteger(timeout) && timeout > 0 ? timeout : DEFAULT_KEY_AGENT_TIMEOUT_MS,
  };
}

function hex(bytes: Uint8Array): string {
  return [...bytes].map((b) => b.toString(16).padStart(2, '0')).join('');
}

async function verifySignature(
  key: Uint8Array,
  signature: string | null,
  body: string
): Promise<boolean> {
  if (!signature) return false;
  try {
    const sig = Uint8Array.from(atob(signature), (c) => c.charCodeAt(0));
    const publicKey = await crypto.subtle.importKey('raw', key, { name: 'Ed25519' }, false, [
      'verify',
    ]);
    return await crypto.subtle.verify(
      { name: 'Ed25519' },
      publicKey,
      sig,
      new TextEncoder().encode(body)
    );
  } catch {
    return false;
  }
}

/** This isolate's secrets if already loaded for the deployment's bundle, else null. */
export function cachedRuntimeSecrets(env: KeyAgentEnv): RuntimeSecrets | null {
  return cached && cached.bundleId === env.SAM_SECRET_BUNDLE_ID ? cached.secrets : null;
}

async function fetchSecrets(agent: AgentSettings): Promise<RuntimeSecrets> {
  const started = Date.now();
  const nonce = hex(crypto.getRandomValues(new Uint8Array(16)));
  let response: Response;
  try {
    response = await fetch(agent.url, {
      method: 'POST',
      headers: { 'content-type': 'application/json', 'x-sam-key-agent': '1' },
      body: JSON.stringify({
        bundleId: agent.bundleId,
        nonce,
        installationId: agent.installationId,
      }),
      redirect: 'manual',
      signal: AbortSignal.timeout(agent.timeoutMs),
    });
  } catch (error) {
    throw new RuntimeSecretsUnavailableError(
      'KEY_AGENT_UNREACHABLE',
      `key agent unreachable (${error instanceof Error ? error.name : 'error'})`
    );
  }
  const text = await response.text().catch(() => '');
  if (response.status !== 200) {
    let error: unknown;
    try {
      error = maybeJsonRecord(JSON.parse(text) as unknown)?.error;
    } catch {
      // never repeat the parser's message: it can quote the body
      error = undefined;
    }
    throw new RuntimeSecretsUnavailableError(
      'KEY_AGENT_REFUSED',
      `key agent answered ${response.status}${typeof error === 'string' ? ` ${error}` : ''}`
    );
  }
  // Whoever answers on the agent's port must prove it opened the bundle: a process that took the
  // port while the agent was down cannot sign this nonce.
  if (!(await verifySignature(agent.verifyKey, response.headers.get(SIGNATURE_HEADER), text))) {
    throw new RuntimeSecretsUnavailableError(
      'KEY_AGENT_UNVERIFIED',
      "key agent answer is not signed by this deployment's agent key"
    );
  }
  let record: JsonRecord = {};
  try {
    record = maybeJsonRecord(JSON.parse(text) as unknown) ?? {};
  } catch {
    // never repeat the parser's message: the body carries the secrets
    record = {};
  }
  const secrets = record.secrets;
  if (
    record.bundleId !== agent.bundleId ||
    record.nonce !== nonce ||
    typeof secrets !== 'object' ||
    secrets === null ||
    Array.isArray(secrets) ||
    Object.entries(secrets).some(
      ([k, v]) => !SECRET_NAME.test(k) || PROTECTED_NAMES.has(k) || typeof v !== 'string'
    )
  ) {
    throw new RuntimeSecretsUnavailableError(
      'KEY_AGENT_BAD_RESPONSE',
      'key agent response is malformed'
    );
  }
  log.info('runtime_secrets.loaded', {
    bundle: agent.bundleId.slice(0, 8),
    count: Object.keys(secrets).length,
    ms: Date.now() - started,
  });
  return Object.freeze({ ...(secrets as Record<string, string>) });
}

/**
 * The deployment's secrets: from this isolate's memory, else one request to the key agent shared
 * by every caller that arrives while it runs. A failure is not cached, so the next request
 * retries (a refused connection fails in about a millisecond).
 */
export async function loadRuntimeSecrets(env: KeyAgentEnv): Promise<RuntimeSecrets> {
  const hit = cachedRuntimeSecrets(env);
  if (hit) return hit;
  const agent = settings(env);
  const { bundleId } = agent;
  if (!inflight || inflight.bundleId !== bundleId) {
    const promise = fetchSecrets(agent).then(
      (secrets) => {
        cached = { bundleId, secrets };
        return secrets;
      },
      (error: unknown) => {
        throw error;
      }
    );
    const entry = { bundleId, promise };
    inflight = entry;
    promise
      .then(
        () => undefined,
        () => undefined
      )
      .finally(() => {
        if (inflight === entry) inflight = null;
      });
  }
  return await inflight.promise;
}

/**
 * `env` with the secrets laid over it: a new object, the runtime's env is never mutated. A secret
 * may replace a string var (as a secrets.env override did before), never a binding.
 *
 * Also registers this bundle's previous AES keys, if a key rotation is in progress
 * (`<NAME>_PREVIOUS`, key-rotation/keys.ts), as the read fallback of `decrypt` / `decryptFile`
 * (services/encryption-key-fallback.ts), and clears them when the bundle has none.
 */
export function withRuntimeSecrets<E extends object>(env: E, secrets: RuntimeSecrets): E {
  const merged: Record<string, unknown> = { ...(env as Record<string, unknown>) };
  for (const [name, value] of Object.entries(secrets)) {
    const existing = merged[name];
    if (existing === undefined || typeof existing === 'string') merged[name] = value;
  }
  if (typeof merged.ENCRYPTION_KEY === 'string') {
    setPreviousEncryptionKeys(previousKeyPairs(merged as unknown as AesKeyEnv));
  }
  return merged as E;
}

function unavailableResponse(error: unknown): Response {
  const code = error instanceof RuntimeSecretsUnavailableError ? error.code : 'SECRETS_UNAVAILABLE';
  log.error('runtime_secrets.unavailable', {
    code,
    message: error instanceof Error ? error.message : String(error),
    action: 'rejected',
  });
  return Response.json(
    {
      error: 'SECRETS_UNAVAILABLE',
      code,
      message: 'This SAM install cannot reach its key agent. Check `docker compose ps key-agent`.',
    },
    { status: 503, headers: { 'retry-after': '5', 'cache-control': 'no-store' } }
  );
}

interface WorkerHandlers<E> {
  fetch?: (request: Request, env: E, ctx: ExecutionContext) => Response | Promise<Response>;
  scheduled?: (
    controller: ScheduledController,
    env: E,
    ctx: ExecutionContext
  ) => void | Promise<void>;
  email?: (message: ForwardableEmailMessage, env: E, ctx: ExecutionContext) => void | Promise<void>;
}

/** The Worker's handlers, each run with the runtime secrets or not at all. */
export function wrapWorker<E extends object>(worker: WorkerHandlers<E>): WorkerHandlers<E> {
  const wrapped: WorkerHandlers<E> = {};
  if (worker.fetch) {
    const inner = worker.fetch;
    wrapped.fetch = async (request, env, ctx) => {
      let secrets: RuntimeSecrets;
      try {
        secrets = await loadRuntimeSecrets(env as KeyAgentEnv);
      } catch (error) {
        return unavailableResponse(error);
      }
      const merged = withRuntimeSecrets(env, secrets);
      // The rotation's control path never reaches the app (key-rotation/control.ts). Loaded on
      // demand: the handler pulls in the passes and their dependencies, which no other request
      // (and no tool that loads this module, like the migration preflight) needs.
      if (new URL(request.url).pathname === KEY_ROTATION_PATH) {
        const control = await import('./key-rotation/control');
        return await control.handleKeyRotationRequest(
          request,
          merged as unknown as import('./key-rotation/control').KeyRotationEnv
        );
      }
      return await inner(request, merged, ctx);
    };
  }
  if (worker.scheduled) {
    const inner = worker.scheduled;
    wrapped.scheduled = async (controller, env, ctx) => {
      // Throws when unavailable: the cron run fails visibly instead of running without keys.
      const secrets = await loadRuntimeSecrets(env as KeyAgentEnv);
      await inner(controller, withRuntimeSecrets(env, secrets), ctx);
    };
  }
  if (worker.email) {
    const inner = worker.email;
    wrapped.email = async (message, env, ctx) => {
      const secrets = await loadRuntimeSecrets(env as KeyAgentEnv);
      await inner(message, withRuntimeSecrets(env, secrets), ctx);
    };
  }
  return wrapped;
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any -- a mixin constructor must accept any arguments
type DurableObjectClass = abstract new (...args: any[]) => object;

/**
 * A Durable Object class whose instances see the runtime secrets in `env`. The constructor gets
 * a copy of the runtime's env; when this isolate already has the secrets they are in it before
 * the original constructor runs, otherwise `blockConcurrencyWhile` holds every event until they
 * are, and a failure there fails the object's events (fail closed).
 */
export function wrapDurableObject<C extends DurableObjectClass>(Base: C): C {
  // @ts-expect-error -- TS cannot type a mixin over an abstract constructor with a custom constructor
  class WithRuntimeSecrets extends Base {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any -- forwards the runtime's arguments
    constructor(...args: any[]) {
      const [ctx, env] = args as [DurableObjectState, KeyAgentEnv & Record<string, unknown>];
      const hit = cachedRuntimeSecrets(env);
      const merged: Record<string, unknown> = hit ? withRuntimeSecrets(env, hit) : { ...env };
      super(ctx, merged, ...args.slice(2));
      if (!hit) {
        void ctx.blockConcurrencyWhile(async () => {
          Object.assign(merged, withRuntimeSecrets(env, await loadRuntimeSecrets(env)));
        });
      }
    }
  }
  return WithRuntimeSecrets as unknown as C;
}
